#!/usr/bin/env bash
# Question 6: kubectl stopped working. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q6_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q6_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q6_NS}
spec:
  replicas: 0
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          resources:
            requests: { cpu: 10m, memory: 16Mi }
EOF

case "${Q6_FAULT}" in
  kubeconfig-server-port)
    kubectl -n "${Q6_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q6_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^([[:space:]]*server: https://[^[:space:]]+):6443$#\1:6433#' /root/.kube/config
    grep -qE -- 'server: https://[^[:space:]]+:6433$' /root/.kube/config || { echo "could not modify /root/.kube/config" >&2; exit 1; }
    sed -i -E 's#^([[:space:]]*server: https://[^[:space:]]+):6443$#\1:6433#' /home/ubuntu/.kube/config
    grep -qE -- 'server: https://[^[:space:]]+:6433$' /home/ubuntu/.kube/config || { echo "could not modify /home/ubuntu/.kube/config" >&2; exit 1; }
    ;;
  kubeconfig-wrong-ca)
    kubectl -n "${Q6_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q6_NS}" rollout status deployment/web --timeout=240s
    for f in /root/.kube/config /home/ubuntu/.kube/config; do
      kubectl config --kubeconfig "$f" set clusters.kubernetes.certificate-authority-data "$(base64 -w0 /etc/kubernetes/pki/front-proxy-ca.crt)" >/dev/null
    done
    ;;
  apiserver-client-ca)
    kubectl -n "${Q6_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q6_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^([[:space:]]*- --client-ca-file=/etc/kubernetes/pki/ca)\.crt$#\1.cert#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --client-ca-file=/etc/kubernetes/pki/ca.cert$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-secure-port)
    kubectl -n "${Q6_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q6_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^([[:space:]]*- --secure-port=)6443$#\16444#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '- --secure-port=6444$' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  apiserver-manifest-yaml)
    kubectl -n "${Q6_NS}" scale deployment/web --replicas=2
    kubectl -n "${Q6_NS}" rollout status deployment/web --timeout=240s
    sed -i -E 's#^    image: (registry\.k8s\.io/kube-apiserver:)#   image: \1#' /etc/kubernetes/manifests/kube-apiserver.yaml
    grep -qE -- '^   image: registry.k8s.io/kube-apiserver:' /etc/kubernetes/manifests/kube-apiserver.yaml || { echo "could not modify /etc/kubernetes/manifests/kube-apiserver.yaml" >&2; exit 1; }
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

case "${Q6_FAULT}" in
  kubeconfig-server-port)
    for _ in $(seq 1 30); do
      [[ "$(for f in /root/.kube/config /home/ubuntu/.kube/config; do kubectl --kubeconfig "$f" get --raw /readyz 2>/dev/null || echo fail; echo; done | xargs)" == "fail fail" ]] && exit 0
      sleep 2
    done
    echo "kubectl still works with the user kubeconfigs" >&2
    exit 1
    ;;
  kubeconfig-wrong-ca)
    for _ in $(seq 1 30); do
      [[ "$(for f in /root/.kube/config /home/ubuntu/.kube/config; do kubectl --kubeconfig "$f" get --raw /readyz 2>/dev/null || echo fail; echo; done | xargs)" == "fail fail" ]] && exit 0
      sleep 2
    done
    echo "kubectl still works with the user kubeconfigs" >&2
    exit 1
    ;;
  apiserver-client-ca)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-secure-port)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
  apiserver-manifest-yaml)
    for _ in $(seq 1 90); do
      [[ "$(curl -sk --max-time 3 https://127.0.0.1:6443/readyz 2>/dev/null || true)" != ok ]] && exit 0
      sleep 2
    done
    echo "the API server is still healthy" >&2
    exit 1
    ;;
esac
